import 'package:flutter/material.dart';import 'package:mobile_scanner/mobile_scanner.dart';import '../data/app_database.dart';import '../data/product.dart';
class ScanPage extends StatefulWidget{const ScanPage({super.key,required this.datasetId,required this.onBarcode,required this.onManual});final String datasetId;final ValueChanged<String> onBarcode;final VoidCallback onManual;@override State<ScanPage> createState()=>_ScanPageState();}
class _ScanPageState extends State<ScanPage>{final controller=MobileScannerController(detectionSpeed:DetectionSpeed.noDuplicates);bool scanned=false;Product? last;@override void dispose(){controller.dispose();super.dispose();}Future<void> detect(BarcodeCapture c) async{if(scanned)return;final v=c.barcodes.firstOrNull?.rawValue?.trim();if(v==null||v.isEmpty)return;scanned=true;await controller.stop();last=await AppDatabase.instance.productByBarcode(widget.datasetId,v);if(!mounted)return;ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(last==null?'تم التقاط الباركود: $v':'المنتج موجود: ${last!.name}')));widget.onBarcode(v);}
 Future<void> manual() async{final c=TextEditingController();final v=await showDialog<String>(context:context,builder:(ctx)=>AlertDialog(title:const Text('إدخال الباركود يدويًا'),content:TextField(controller:c,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'الباركود')),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(ctx,c.text.trim()),child:const Text('متابعة'))]));if(v!=null&&v.isNotEmpty)widget.onBarcode(v);}
 @override Widget build(BuildContext context)=>Padding(padding:const EdgeInsets.all(16),child:Column(children:[Expanded(child:ClipRRect(borderRadius:BorderRadius.circular(28),child:Stack(fit:StackFit.expand,children:[MobileScanner(controller:controller,onDetect:detect),IgnorePointer(child:Center(child:Container(width:260,height:170,decoration:BoxDecoration(border:Border.all(color:const Color(0xFF2DD4A7),width:3),borderRadius:BorderRadius.circular(18))))),const Positioned(bottom:20,left:0,right:0,child:Text('وجّه الكاميرا نحو الباركود',textAlign:TextAlign.center,style:TextStyle(color:Colors.white,fontWeight:FontWeight.w700)))]))),const SizedBox(height:12),Row(children:[Expanded(child:OutlinedButton.icon(onPressed:()=>controller.toggleTorch(),icon:const Icon(Icons.flash_on),label:const Text('الفلاش'))),const SizedBox(width:8),Expanded(child:OutlinedButton.icon(onPressed:manual,icon:const Icon(Icons.keyboard),label:const Text('يدوي')))]),const SizedBox(height:10),Card(child:ListTile(leading:const Icon(Icons.qr_code_2),title:Text(last?.name??'آخر منتج ممسوح'),subtitle:Text(last?.barcode??'امسح باركودًا للبدء')))]));}
}
